public class Solution {
    // CONTRACT: sum of the elements at EVEN indexes (0, 2, 4, ...).
    public static int sumEvenIndexes(int[] arr) {
        int total = 0;
        for (int i = 0; i <= arr.length; i++) {
            if (i % 2 == 0) {
                total += arr[i];
            }
        }
        return total;
    }
}
